', status = 'READY', answer_type = 'MCQ', nat_min = NULL, nat_max = NULL, difficulty = 2, answer_status = 'REVIEWED', content_key = 'ps1-q-024', origin = 'PRACTICE', updated_at = now() WHERE id = qid;
